12	// Stripe requires the raw body for signature verification.
13	export const runtime = "nodejs";
14	
15	export async function POST(req: Request) {
16	  const sig = req.headers.get("stripe-signature");
17	  const [REDACTED];
18	
19	  // Read + archive the raw body BEFORE any header / config check so we
20	  // capture *every* inbound request — forged payloads, misconfigured
21	  // deploys missing the webhook secret, anything. The 90-day TTL plus
22	  // 1 MiB body cap on the archive bound storage abuse.
23	  const raw = await req.text();
24	  const archiveId = await archiveWebhookPayload({
25	    provider: "stripe",
26	    headers: req.headers,
27	    rawBody: raw,
28	  });
29	
30	  if (!sig || !secret) {
31	    await updateWebhookPayloadStatus(archiveId, {
32	      signatureVerified: false,
33	      processingStatus: "failed",
34	      processingError: "missing signature config",
35	    });
36	    return NextResponse.json(
37	      { ok: false, error: "missing signature config" },
38	      { status: 400 },
39	    );
40	  }
41	
42	  let event: Stripe.Event;
43	  try {
44	    event = getStripe().webhooks.constructEvent(raw, sig, secret);
45	  } catch (e) {
46	    await updateWebhookPayloadStatus(archiveId, {
47	      signatureVerified: false,
48	      processingStatus: "failed",
49	      processingError: e instanceof Error ? e.message : "verify failed",
50	    });
51	    return NextResponse.json(
52	      { ok: false, error: e instanceof Error ? e.message : "verify failed" },
53	      { status: 400 },
54	    );
55	  }
56	
57	  await updateWebhookPayloadStatus(archiveId, {
58	    signatureVerified: true,
59	    processingStatus: "verified",
60	    eventId: event.id,
61	  });
62	
