1	"use client";
2	
3	import { useMemo, useState, useTransition } from "react";
4	import { Button } from "@/components/ui/button";
5	import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
6	import { Input } from "@/components/ui/input";
7	import { Label } from "@/components/ui/label";
8	import { Textarea } from "@/components/ui/textarea";
9	import { Checkbox } from "@/components/ui/checkbox";
10	import { Slider } from "@/components/ui/slider";
11	import {
12	  Select,
13	  SelectContent,
14	  SelectItem,
15	  SelectTrigger,
16	  SelectValue,
17	} from "@/components/ui/select";
18	import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
19	import { toast } from "sonner";
20	import { calculate, formatCents } from "@/lib/pricing/engine";
21	import type { PricingConfig, ProjectType, Term } from "@/lib/pricing/types";
22	import type { ActionResult } from "@/lib/actions/result";
23	import type { ClientRow, QuoteRow } from "@/lib/db/types";
24	import type { QuoteInputT } from "@/lib/validation/schemas";
25	
26	interface Props {
27	  config: PricingConfig;
28	  clients: ClientRow[];
29	  initialClientId?: string;
30	  existing?: QuoteRow;
31	  onSave: (input: QuoteInputT) => Promise<ActionResult<{ id: string }>>;
32	  saveLabel: string;
33	}
34	
35	type ScopeSelection = Record<string, { enabled: boolean; qty?: number }>;
36	
37	export function QuoteBuilder({
38	  config,
39	  clients,
40	  initialClientId,
41	  existing,
42	  onSave,
43	  saveLabel,
44	}: Props) {
45	  const [clientId, setClientId] = useState(
46	    existing?.client_id ?? initialClientId ?? "",
47	  );
48	  const [projectName, setProjectName] = useState(existing?.project_name ?? "");
49	  const [projectType, setProjectType] = useState<ProjectType>(
50	    existing?.project_type ?? "marketing",
51	  );
52	  const [tier, setTier] = useState<string>(existing?.tier ?? "growth");
53	  const [term, setTerm] = useState<Term>(existing?.term ?? "monthly");
54	  const [setupSel, setSetupSel] = useState<ScopeSelection>(
55	    existing?.scope.setup ?? {},
56	  );
57	  const [recurringSel, setRecurringSel] = useState<ScopeSelection>(
58	    existing?.scope.recurring ?? {},
59	  );
60	  const [oneTimeSel, setOneTimeSel] = useState<ScopeSelection>(
61	    existing?.scope.oneTime ?? {},
62	  );
63	  const [websiteSel, setWebsiteSel] = useState<ScopeSelection>(
64	    existing?.scope.website ?? {},
65	  );
66	  const [rush, setRush] = useState(existing?.multipliers.rush ?? 0);
67	  const [highTouch, setHighTouch] = useState(
68	    existing?.multipliers.highTouch ?? 0,
69	  );
70	  const [familyCourtesy, setFamilyCourtesy] = useState(
71	    existing?.multipliers.familyCourtesy ?? 0,
72	  );
73	  const [consultingHours, setConsultingHours] = useState(
74	    existing?.custom_consulting?.hours ?? 10,
75	  );
76	  const [consultingRate, setConsultingRate] = useState(
77	    (existing?.custom_consulting?.rateCents ?? 25000) / 100,
78	  );
79	  const [consultingDesc, setConsultingDesc] = useState(
80	    existing?.custom_consulting?.description ?? "",
81	  );
82	  const [internalNotes, setInternalNotes] = useState(
83	    existing?.internal_notes ?? "",
84	  );
85	
86	  const [isPending, startTransition] = useTransition();
87	
88	  const calc = useMemo(() => {
89	    if (!clientId) return null;
90	    try {
91	      return calculate(
92	        {
93	          projectType,
94	          tier: projectType === "marketing" ? tier : undefined,
95	          scope: {
96	            setup: setupSel,
97	            recurring: recurringSel,
98	            oneTime: oneTimeSel,
99	            website: websiteSel,
100	          },
101	          multipliers: { rush, highTouch, familyCourtesy },
102	          term,
103	          customConsulting:
104	            projectType === "consulting"
105	              ? {
106	                  hours: consultingHours,
107	                  rateCents: Math.round(consultingRate * 100),
108	                  description: consultingDesc,
109	                }
110	              : undefined,
111	        },
112	        config,
113	      );
114	    } catch {
115	      return null;
116	    }
117	  }, [
118	    clientId,
119	    projectType,
