"use server";

import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { ok, fail, type ActionResult } from "@/lib/actions/result";
import { QuoteInput, type QuoteInputT } from "@/lib/validation/schemas";
import { requireUser } from "@/lib/auth/current-user";
import { recordAudit } from "@/lib/db/audit";
import { calculate } from "@/lib/pricing/engine";
import { getActivePricingConfig } from "@/lib/db/pricing-config";
import {
  createQuoteDraft,
  softDeleteQuote,
  transitionQuoteStatus,
  updateQuoteDraft,
} from "@/lib/db/quotes";
import type { CalcResult, QuoteStatus } from "@/lib/pricing/types";

function calcOrNull(
  input: QuoteInputT,
  configJson: unknown,
): CalcResult | null {
  try {
    return calculate(
      {
        projectType: input.project_type,
        tier: input.tier ?? undefined,
        scope: input.scope,
        multipliers: input.multipliers,
        term: input.term,
        customConsulting: input.custom_consulting ?? undefined,
      },
      configJson as never,
    );
  } catch {
    return null;
  }
}

export async function createQuoteAction(
  input: QuoteInputT,
): Promise<ActionResult<{ id: string }>> {
  let user;
  try {
    user = await requireUser();
  } catch {
    return fail("Sign in required.", "unauthorized");
  }

  const parsed = QuoteInput.safeParse(input);
  if (!parsed.success) {
    return fail(
      "Validation failed",
      "validation_failed",
      parsed.error.flatten().fieldErrors as Record<string, string[]>,
    );
  }

  const active = await getActivePricingConfig();
  if (!active)
    return fail("No active pricing config. Publish one first.", "conflict");

  const calc = calcOrNull(parsed.data, active.config);
  if (!calc) return fail("Pricing calculation failed.", "internal_error");

  try {
    const row = await createQuoteDraft(parsed.data, active.id, calc);
    await recordAudit({
      actorId: user.id,
      action: "quote.draft.create",
      entityType: "quote",
      entityId: row.id,
      diff: {
        client_id: row.client_id,
        first_month_cents: calc.firstMonthTotalCents,
      },
    });
    revalidatePath("/admin/quotes");
    return ok({ id: row.id });
  } catch (e) {
    return fail(e instanceof Error ? e.message : "Failed to create quote");
  }
}

export async function updateQuoteAction(
  id: string,
  input: QuoteInputT,
): Promise<ActionResult<{ id: string }>> {
  let user;
  try {
    user = await requireUser();
  } catch {
    return fail("Sign in required.", "unauthorized");
  }

  const parsed = QuoteInput.safeParse(input);
  if (!parsed.success) {
    return fail(
      "Validation failed",
      "validation_failed",
      parsed.error.flatten().fieldErrors as Record<string, string[]>,
    );
  }

  const active = await getActivePricingConfig();
  if (!active) return fail("No active pricing config.", "conflict");

  const calc = calcOrNull(parsed.data, active.config);
  if (!calc) return fail("Pricing calculation failed.", "internal_error");

  try {
    const row = await updateQuoteDraft(id, parsed.data, calc);
    await recordAudit({
      actorId: user.id,
      action: "quote.draft.update",
      entityType: "quote",
      entityId: row.id,
    });
    revalidatePath(`/admin/quotes/${id}`);
    return ok({ id: row.id });
  } catch (e) {
    return fail(e instanceof Error ? e.message : "Failed to update quote");
  }
}

export async function transitionQuoteAction(
  formData: FormData,
): Promise<ActionResult<null>> {
  const id = String(formData.get("id") ?? "");
  const next = String(formData.get("status") ?? "") as QuoteStatus;
  if (!id || !next) return fail("Missing id/status", "validation_failed");

  let user;
  try {
    user = await requireUser();
  } catch {
    return fail("Sign in required.", "unauthorized");
  }

  const allowed: QuoteStatus[] = ["sent", "lost", "void"];
  if (!allowed.includes(next)) {
    return fail(
      "Status transition not allowed from admin.",
      "validation_failed",
    );
  }

  try {
    const row = await transitionQuoteStatus(id, next);
    await recordAudit({
      actorId: user.id,
      action: `quote.status.${next}`,
      entityType: "quote",
      entityId: row.id,
      diff: { status: next },
    });
    revalidatePath(`/admin/quotes/${id}`);
    revalidatePath("/admin/quotes");
    return ok(null);
  } catch (e) {
    return fail(e instanceof Error ? e.message : "Failed to update status");
  }
}

export async function deleteQuoteAction(
  formData: FormData,
): Promise<ActionResult<null>> {
  const id = String(formData.get("id") ?? "");
  if (!id) return fail("Missing id", "validation_failed");

  let user;
  try {
    user = await requireUser();
  } catch {
    return fail("Sign in required.", "unauthorized");
  }

  try {
    await softDeleteQuote(id);
    await recordAudit({
      actorId: user.id,
      action: "quote.soft_delete",
      entityType: "quote",
      entityId: id,
    });
    revalidatePath("/admin/quotes");
    return ok(null);
  } catch (e) {
    return fail(e instanceof Error ? e.message : "Failed to delete");
  }
}

export async function createQuoteAndRedirect(input: QuoteInputT) {
  const result = await createQuoteAction(input);
  if (result.ok) redirect(`/admin/quotes/${result.data.id}`);
  return result;
}

import { z } from "zod";

// ---------------------------------------------------------------------------
// CLIENT
// ---------------------------------------------------------------------------

export const RelationshipTag = z.enum([
  "standard",
  "family",
  "partner",
  "high_touch",
  "priority",
]);

export const ClientInput = z.object({
  company: z.string().trim().min(1, "Company is required").max(200),
  contact_name: z.string().trim().max(200).optional().or(z.literal("")),
  email: z
    .string()
    .trim()
    .email("Enter a valid email")
    .optional()
    .or(z.literal("")),
  phone: z.string().trim().max(40).optional().or(z.literal("")),
  address: z.string().trim().max(400).optional().or(z.literal("")),
  notes: z.string().trim().max(2000).optional().or(z.literal("")),
  relationship_tag: RelationshipTag.default("standard"),
});

export type ClientInputT = z.infer<typeof ClientInput>;

// ---------------------------------------------------------------------------
// QUOTE
// ---------------------------------------------------------------------------

export const ProjectType = z.enum(["marketing", "website", "consulting"]);
export const Term = z.enum(["monthly", "six", "twelve"]);

const QuoteScopeSchema = z
  .object({
    setup: z
      .record(
        z.string(),
        z.object({
          enabled: z.boolean(),
          qty: z.number().int().min(1).optional(),
        }),
      )
      .optional(),
    recurring: z
      .record(
        z.string(),
        z.object({
          enabled: z.boolean(),
          qty: z.number().int().min(1).optional(),
        }),
      )
      .optional(),
    oneTime: z
      .record(
        z.string(),
        z.object({
          enabled: z.boolean(),
          qty: z.number().int().min(1).optional(),
        }),
      )
      .optional(),
    website: z
      .record(
        z.string(),
        z.object({
          enabled: z.boolean(),
          qty: z.number().int().min(1).optional(),
        }),
      )
      .optional(),
  })
  .default({});

const QuoteMultipliersSchema = z
  .object({
    rush: z.number().min(0).max(100).optional(),
    highTouch: z.number().min(0).max(100).optional(),
    familyCourtesy: z.number().min(0).max(100).optional(),
  })
  .default({});

const CustomConsultingSchema = z.object({
  hours: z.number().min(0.5).max(2000),
  rateCents: z.number().int().min(5000),
  description: z.string().max(500).optional(),
});

export const QuoteInput = z
  .object({
    client_id: z.string().uuid(),
    project_name: z.string().trim().max(200).optional().or(z.literal("")),
    project_type: ProjectType,
    tier: z.string().trim().max(60).optional().nullable(),
    scope: QuoteScopeSchema,
    multipliers: QuoteMultipliersSchema,
    term: Term.default("monthly"),
    custom_consulting: CustomConsultingSchema.optional().nullable(),
    internal_notes: z.string().max(2000).optional().or(z.literal("")),
  })
  .superRefine((v, ctx) => {
    if (v.project_type === "marketing" && !v.tier) {
      ctx.addIssue({
        code: "custom",
        path: ["tier"],
        message: "Marketing retainers require a tier",
      });
    }
    if (v.project_type === "consulting" && !v.custom_consulting) {
      ctx.addIssue({
        code: "custom",
        path: ["custom_consulting"],
        message: "Consulting quotes require hours and rate",
      });
    }
  });

export type QuoteInputT = z.infer<typeof QuoteInput>;

// ---------------------------------------------------------------------------
// PRICING CONFIG (loose — full validation is structural and lives in pricing/types.ts)
// ---------------------------------------------------------------------------

export const PricingConfigDraft = z.object({
  version: z.number().int().min(1),
  config: z.record(z.string(), z.unknown()), // accept any JSON; engine will fail loudly if malformed
  publish: z.boolean().default(false),
});

export type PricingConfigDraftT = z.infer<typeof PricingConfigDraft>;

