    .schema("dts")
    .from(TABLE)
    .select("*")
    .eq("id", id)
    .is("deleted_at", null)
    .maybeSingle();
  if (error) throw new Error(error.message);
  return (data as QuoteRow) ?? null;
}

export async function createQuoteDraft(
  input: QuoteInputT,
  pricingConfigId: string,
  calc: CalcResult,
): Promise<QuoteRow> {
  const supabase = await createServerSupabase();
  const { data, error } = await supabase
    .schema("dts")
    .from(TABLE)
    .insert({
      client_id: input.client_id,
      pricing_config_id: pricingConfigId,
      project_name: input.project_name || null,
      project_type: input.project_type,
      tier: input.tier ?? null,
      scope: input.scope ?? {},
      multipliers: input.multipliers ?? {},
      term: input.term,
      custom_consulting: input.custom_consulting ?? null,
      calc,
      internal_notes: input.internal_notes || null,
      status: "draft",
    })
    .select("*")
    .single();
  if (error) throw new Error(error.message);
  return data as QuoteRow;
}

export async function updateQuoteDraft(
  id: string,
  input: QuoteInputT,
  calc: CalcResult,
): Promise<QuoteRow> {
  const supabase = await createServerSupabase();
  const { data, error } = await supabase
    .schema("dts")
    .from(TABLE)
    .update({
      client_id: input.client_id,
      project_name: input.project_name || null,
      project_type: input.project_type,
      tier: input.tier ?? null,
      scope: input.scope ?? {},
      multipliers: input.multipliers ?? {},
      term: input.term,
      custom_consulting: input.custom_consulting ?? null,
      calc,
      internal_notes: input.internal_notes || null,
    })
    .eq("id", id)
    .eq("status", "draft")
    .select("*")
    .single();
  if (error) throw new Error(error.message);
  return data as QuoteRow;
}

export async function transitionQuoteStatus(
  id: string,
  next: QuoteStatus,
): Promise<QuoteRow> {
  const supabase = await createServerSupabase();
  const updates: Record<string, unknown> = { status: next };
  if (next === "sent") updates.sent_at = new Date().toISOString();
  if (next === "signed") updates.signed_at = new Date().toISOString();
  const { data, error } = await supabase
    .schema("dts")
    .from(TABLE)
    .update(updates)
    .eq("id", id)
    .select("*")
    .single();
  if (error) throw new Error(error.message);
  return data as QuoteRow;
}

export async function softDeleteQuote(id: string): Promise<void> {
  const supabase = await createServerSupabase();
  const { error } = await supabase
    .schema("dts")
    .from(TABLE)
    .update({ deleted_at: new Date().toISOString() })
    .eq("id", id);
  if (error) throw new Error(error.message);
}

