14	// Append-only audit write. Routed to MongoDB (collection: audit_events)
15	// because the table is write-only in app code and Mongo is the
16	// cost-preferred store. Failures are logged but never rethrown — the
17	// user's primary action must not depend on audit succeeding.
18	//
19	// The Promise<void> signature is preserved for backward compatibility
20	// with the ~14 existing `await recordAudit(...)` call sites, but the
21	// actual Mongo write is detached: this function resolves on the next
22	// microtask and never blocks on the database. Hot paths (webhooks,
23	// server actions) cannot stall on a slow or unreachable Mongo.
24	//
25	// Known seam: supabase/migrations/0002_publish_pricing_config_rpc.sql
26	// still INSERTs into the legacy Postgres dts.audit_log table from the
27	// publish_pricing_config() RPC. New writes from app code go to Mongo;
28	// reconcile later.
29	export async function recordAudit(event: AuditEvent): Promise<void> {
30	  appendAuditEvent({
